        "initial": 0.75,
        "upper": 1.5
      }
    ],
    "states": [
      {
        "name": "z0",
        "meaning": "A decaying input trace, initialized at zero; physical interpretation is unverified.",
        "rate": "u-p0*z0"
      }
    ],
    "terms": [
      "x",
      "x**3",
      "tanh(x)",
      "x*tanh(x)**2",
      "u",
      "z0"
    ]
  },
  "observable_consequence": "If the additional odd correction addresses the held-out discrepancy, refitting should reduce trajectory error for schedules reaching larger |x|, while predictions for reset polarity-reversed inputs should remain sign-reversed. Check both consequences on held-out complete input schedules.",
  "analogy": {
    "domain": "odd nonlinear response curves",
    "relation": "An odd saturating correction changes response magnitude with state amplitude without introducing a polarity preference.",
    "mapping": "The measured state x is the curve argument, and x*tanh(x)**2 is the proposed odd correction to the fitted rate.",
    "failure_condition": "The proposal is unsupported if held-out trajectory prediction does not improve, or if polarity-paired outputs depart from sign reversal beyond measurement noise."
  },
